// Long polling de Telegram: no requiere URL pública (ideal para desarrollo local).
const data = $getWorkflowStaticData('global');
return [{ json: { offset: data.offset || 0 } }];

const data = $getWorkflowStaticData('global');
const res = $('Leer mensajes (getUpdates)').first().json;
if (!res.ok || !Array.isArray(res.result) || res.result.length === 0) return [];
data.offset = res.result[res.result.length - 1].update_id + 1;

const items = [];
for (const u of res.result) {
  if (u.message && typeof u.message.text === 'string') {
    const text = u.message.text.trim();
    const [first, ...rest] = text.split(/\s+/);
    const isCommand = first.startsWith('/');
    items.push({ json: {
      kind: 'message', chatId: String(u.message.chat.id), username: u.message.from?.username ?? null,
      firstName: u.message.from?.first_name ?? '', command: isCommand ? first.split('@')[0].toLowerCase() : null,
      args: isCommand ? rest.join(' ').trim() : text, callbackId: null,
    } });
  } else if (u.callback_query) {
    const cq = u.callback_query;
    const [action, value = ''] = String(cq.data || '').split(':');
    items.push({ json: {
      kind: 'callback', chatId: String(cq.message?.chat?.id ?? cq.from.id), username: cq.from?.username ?? null,
      firstName: cq.from?.first_name ?? '', command: action === 'renew' ? '/renovar' : action === 'cmd' ? '/' + value : null,
      args: action === 'renew' ? value : '', callbackId: cq.id,
    } });
  }
}
return items;

const u = $('Separar actualizaciones').item.json;
const who = $json || {};
const user = who.linked ? who.user : null;
const cmd = u.command;
let route = 'ayuda';
if (cmd === '/start' && u.args) route = 'vincular';
else if (['/start', '/ayuda', '/help'].includes(cmd)) route = 'ayuda';
else if (cmd === '/buscar') route = u.args ? 'buscar' : 'ayuda';
else if (cmd === '/disponible') route = u.args ? 'disponible' : 'ayuda';
else if (cmd === '/pregunta') route = u.args ? 'pregunta' : 'ayuda';
else if (['/misprestamos', '/prestamos'].includes(cmd)) route = user ? 'prestamos' : 'sin_vincular';
else if (cmd === '/renovar') route = user ? (u.args ? 'renovar' : 'prestamos') : 'sin_vincular';
else if (cmd === '/multas') route = user ? 'multas' : 'sin_vincular';
else if (!cmd) route = u.args.length >= 3 ? 'pregunta' : 'ayuda'; // texto libre → asistente IA
const ROUTES = ['vincular', 'buscar', 'disponible', 'pregunta', 'prestamos', 'renovar', 'multas', 'ayuda', 'sin_vincular'];
return { json: { ...u, user, route, routeIndex: ROUTES.indexOf(route) } };

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const md = (s) => esc(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/^#{1,3}\s*(.+)$/gm, '<b>$1</b>').replace(/^\s*[-*]\s+/gm, '• ');
const cut = (s) => (s.length > 3900 ? s.slice(0, 3900) + '…' : s);
const avail = (a) => !a ? '' : (a.available > 0 ? `🟢 ${a.available}/${a.total} disponibles` : `🔴 Sin ejemplares (${a.onLoan} prestados)`);
const fmtDate = (iso) => new Date(iso).toLocaleDateString('es-MX', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'America/Mexico_City' });
const failed = (r) => r && (r.statusCode >= 400 || r.error) ? (Array.isArray(r.message) ? r.message.join('. ') : (r.message || r.error || 'Error')) : null;

const req = $('Enrutar').item.json;
const r = $json;
const err = failed(r);
return { json: { chatId: req.chatId, text: err
  ? `❌ No pude vincular tu cuenta: ${esc(err)}\nGenera un código nuevo en la app (Perfil → Vincular Telegram).`
