const s = r.summary || {};
const footer = s.pendingPenalties > 0 ? `\n\n💸 Multas pendientes: $${s.pendingPenalties} ${s.currency || 'MXN'}` : '';
return { json: { chatId: req.chatId, text: `📚 <b>Tus préstamos</b>\n\n${lines.join('\n\n')}${footer}`,
